class Solution:
    def jump(self, nums: List[int]) -> int:
        jumps, lo, hi = 0, 0, 0
        while hi < len(nums) - 1:
            lo, hi = hi + 1, max(i + nums[i] for i in range(lo, hi + 1))
            jumps += 1
        return jumps

